package vn.iotstar.config;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import vn.iotstar.security.CustomUserDetailsService;@Configuration public class SecurityConfig{public SecurityConfig(CustomUserDetailsService uds){this.uds=uds;}final CustomUserDetailsService uds;@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}@Bean SecurityFilterChain securityFilterChain(HttpSecurity http)throws Exception{http.userDetailsService(uds).authorizeHttpRequests(a->a.requestMatchers("/","/login","/register","/verify-otp","/forgot-password","/reset-password","/resend-register-otp","/css/**","/js/**","/images/**","/error").permitAll().requestMatchers("/users/**").hasRole("ADMIN").requestMatchers("/products/**").authenticated().anyRequest().authenticated()).formLogin(f->f.loginPage("/login").loginProcessingUrl("/login").usernameParameter("username").passwordParameter("password").defaultSuccessUrl("/",true).failureUrl("/login?error=true").permitAll()).logout(l->l.logoutUrl("/logout").logoutSuccessUrl("/login?logout=true").invalidateHttpSession(true).deleteCookies("JSESSIONID").permitAll()).sessionManagement(s->s.maximumSessions(1).maxSessionsPreventsLogin(false));return http.build();}}
